import java.util.*;

class Solution {
    public int[][] merge(int[][] intervals) {
        List<int[]> list = new ArrayList<>();
        for (int[] iv : intervals) list.add(new int[]{iv[0], iv[1]});

        boolean merged = true;
        while (merged) {
            merged = false;
            outer:
            for (int i = 0; i < list.size(); i++) {
                for (int j = i + 1; j < list.size(); j++) {
                    int[] a = list.get(i);
                    int[] b = list.get(j);
                    // 有重叠：a 的右端 >= b 的左端，且 b 的右端 >= a 的左端
                    if (a[1] >= b[0] && b[1] >= a[0]) {
                        int[] nu = new int[]{Math.min(a[0], b[0]), Math.max(a[1], b[1])};
                        list.remove(j);   // 先删大下标，避免后面下标前移
                        list.remove(i);
                        list.add(nu);
                        merged = true;
                        break outer;      // 合并后列表变了，必须重新扫
                    }
                }
            }
        }
        return list.toArray(new int[0][]);
    }
}

import java.util.*;

class Solution {
    public int[][] merge(int[][] intervals) {
        if (intervals.length == 0) return new int[0][];
        // 按左端点升序；左端点相同则按右端点升序
        Arrays.sort(intervals, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);

        List<int[]> ans = new ArrayList<>();
        int[] cur = new int[]{intervals[0][0], intervals[0][1]};

        for (int i = 1; i < intervals.length; i++) {
            if (intervals[i][0] <= cur[1]) {
                // 能接上：延长当前区间的右端（取两者更大的）
                cur[1] = Math.max(cur[1], intervals[i][1]);
            } else {
                // 接不上：当前区间定型，开始下一个
                ans.add(cur);
                cur = new int[]{intervals[i][0], intervals[i][1]};
            }
        }
        ans.add(cur);   // 最后一个别忘了
        return ans.toArray(new int[0][]);
    }
}

import java.util.*;

class Solution {
    public int[][] merge(int[][] intervals) {
        if (intervals.length <= 1) return intervals;
        Arrays.sort(intervals, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);

        int k = 1;   // k 表示已写好的区间个数，位置 0 已就位
        for (int i = 1; i < intervals.length; i++) {
            if (intervals[i][0] <= intervals[k - 1][1]) {
                // 能接上，只延长已有区间的右端，k 不动
                intervals[k - 1][1] = Math.max(intervals[k - 1][1], intervals[i][1]);
            } else {
                // 接不上，把新区间搬到 k 位置
                intervals[k] = intervals[i];
                k++;
            }
        }
        return Arrays.copyOf(intervals, k);
    }
}
